export const getCreateShootUrl = () => {




  return `/api/shoots`
}

/**
 * The flexible format accepts one to six product references and queues an eight-frame campaign. The strict front/back format requires exactly two references and queues seven final images.
 *   Open-source AI model requests are routed to the authenticated Colab
 *   GPU worker. FLUX.2 Pro is available through separate fal.ai and
 *   Black Forest Labs server-side image-editing routes. CPU preview is
 *   explicitly a source-preserved product compositor, not AI generation.
 * @summary Queue a selectable luxury product campaign
 */
export const createShoot = async (createShootInput: CreateShootInput, options?: RequestInit): Promise<Shoot> => {
    const formData = new FormData();
if(createShootInput.product_name !== undefined) {
 formData.append(`product_name`, createShootInput.product_name);
 }
if(createShootInput.category !== undefined) {
 formData.append(`category`, createShootInput.category);
 }
if(createShootInput.atmosphere !== undefined) {
 formData.append(`atmosphere`, createShootInput.atmosphere);
 }
if(createShootInput.background !== undefined) {
 formData.append(`background`, createShootInput.background);
 }
if(createShootInput.output_format !== undefined) {
 formData.append(`output_format`, createShootInput.output_format);
 }
if(createShootInput.engine !== undefined) {
 formData.append(`engine`, createShootInput.engine);
 }
if(createShootInput.speed_mode !== undefined) {
 formData.append(`speed_mode`, createShootInput.speed_mode);
 }
if(createShootInput.campaign_format !== undefined) {
 formData.append(`campaign_format`, createShootInput.campaign_format);
 }
if(createShootInput.generation_mode !== undefined) {
 formData.append(`generation_mode`, createShootInput.generation_mode);
 }
createShootInput.references.forEach(value => formData.append(`references`, value));

  return customFetch<Shoot>(getCreateShootUrl(),
  {
    ...options,
    method: 'POST'
    ,
    body: formData
  }
);}





